function login() {
  let une = source.getLoginInfoMap().get("账号")
  let pwd = source.getLoginInfoMap().get("密码")
  if (une && pwd) {
    let body = String('username=' + une + '&password=' + pwd + '&usecookie=315360000&action=login')
    let url = source.bookSourceUrl + '/login.php'
    let headers = Object.assign({}, JSON.parse(source.header), { "Content-Type": "application/x-www-form-urlencoded"})
    let ck = java.post(url, body, headers).cookies();
    let loginHeader = JSON.stringify({
      "Cookie": String(ck).match(/\{(.*?)\}/)[1].replace(/,/g, ';')
    })
    source.putLoginHeader(loginHeader)
  }
}

