    tz = tz == -1 ? '' : '已有' + tz + '人投资本书';
    //状态
    let zt = gets('$.*.BaseBookInfo.BookStatus');
    //最新VIP章节
    let lcv = gets('$.*.BaseBookInfo.ChapterInfo.LastVipUpdateChapterName');
    //最新章节
    let lc = gets('$.*.BaseBookInfo.ChapterInfo.LastUpdateChapterName');
    //最新时间免费
